import six
from taf.analyzer.aasyslog_throughput.throughput_data import (FixedDevicesThroughputDataCollection,
                                                              DynamicDevicesThroughputDataCollection)
from taf.analyzer.aasyslog_throughput.cell import (CellThroughputData, CAFixedCellsThroughputDataCollection)
from taf.analyzer.aasyslog_throughput.calculator import (PeakCalculator, AverageCalculator, MinimumCalculator, CABuffer,
                                                         CAPeakCalculator, CAMinimumCalculator, CAAverageCalculator)
from taf.analyzer.aasyslog_throughput.throughput import Throughput
from taf.analyzer.aasyslog_throughput.reader import WAFileReader as InternalReader
from taf.analyzer.aasyslog_throughput.reader import Reader
from taf.analyzer.aasyslog_throughput.filter import UplinkOnCellFilter, DownlinkOnCellFilter
from taf.analyzer.aasyslog_throughput.recorder import Recorder, DictRecorder, DoNothingRecorder, CSVRecorder


def create_reader(log):
    if not log:
        return InternalReader(log)

    return log if issubclass(log.__class__, Reader) else InternalReader(log)


class ThroughtputFactory(object):
    def _create_recorder(self, throughput_records_output):
        if throughput_records_output is None:
            return DoNothingRecorder()

        if isinstance(throughput_records_output, dict):
            return DictRecorder(throughput_records_output)

        if isinstance(throughput_records_output, six.string_types):
            return CSVRecorder(throughput_records_output)

        if issubclass(type(throughput_records_output), Recorder):
            return throughput_records_output


class UplinkThroughputFactory(ThroughtputFactory):

    def create(self, cells=None, log=None, throughput_records_output=None):
        reader = create_reader(log)
        throughput_filter = UplinkOnCellFilter(reader, throughput_data_factory=CellThroughputData)
        calculators = [PeakCalculator(), AverageCalculator(), MinimumCalculator()]
        cell_data_collection = FixedDevicesThroughputDataCollection(cells, throughput_data_factory=CellThroughputData) \
            if cells else DynamicDevicesThroughputDataCollection()
        recorder = self._create_recorder(throughput_records_output)
        return Throughput(cell_data_collection, throughput_filter, calculators, recorder)


class DownlinkThroughputFactory(ThroughtputFactory):
    def create(self, cells=None, log=None, throughput_records_output=None):
        reader = create_reader(log)
        throughput_filter = DownlinkOnCellFilter(reader, throughput_data_factory=CellThroughputData)
        calculators = [PeakCalculator(), AverageCalculator(), MinimumCalculator()]
        cell_data_collection = FixedDevicesThroughputDataCollection(cells, throughput_data_factory=CellThroughputData) \
            if cells else DynamicDevicesThroughputDataCollection()
        recorder = self._create_recorder(throughput_records_output)
        return Throughput(cell_data_collection, throughput_filter, calculators, recorder)


class CAUplinkThroughputFactory(ThroughtputFactory):
    def create(self, cells, log=None, throughput_records_output=None):
        reader = create_reader(log)
        throughput_filter = UplinkOnCellFilter(reader, throughput_data_factory=CellThroughputData)
        calculators = [CAPeakCalculator(CABuffer(cells)), CAAverageCalculator(CABuffer(cells)),
                       CAMinimumCalculator(CABuffer(cells))]
        cell_data_collection = CAFixedCellsThroughputDataCollection(cells)
        recorder = self._create_recorder(throughput_records_output)
        return Throughput(cell_data_collection, throughput_filter, calculators, recorder)


