        reader = create_reader(log)
        throughput_filter = DownlinkOnCellFilter(reader, throughput_data_factory=CellThroughputData)
        calculators = [CAPeakCalculator(CABuffer(cells)), CAAverageCalculator(CABuffer(cells)),
                       CAMinimumCalculator(CABuffer(cells))]
        cell_data_collection = CAFixedCellsThroughputDataCollection(cells)
        recorder = self._create_recorder(throughput_records_output)
        return Throughput(cell_data_collection, throughput_filter, calculators, recorder)
